// Написан autotest-writer вручную (три контекста одной роли с разной эмулированной геолокацией — генератор так не умеет).
// spec: .qa/e2e/specs/location-map.md 4.1 · кейс .qa/tests/location-map/LOC-09 · тикет #6575d3 (раунд 12, 18.11.2026)
// @data: меняет место reg5 (Or-Akiva) → в finally возвращается Тель-Авив; шаринг у reg5 должен быть ВКЛ (если ВЫКЛ — тест включает и выключает обратно).
// Сессия .qa/auth/reg5.json сейчас пуста — перед прогоном npm run qa-login:manual -- reg5.
// Не проверен на живой странице: имя запроса `record_location` взято из брифа (#b2f39b «0 record_location при ВЫКЛ/ВЫКЛ»), формат тела — предположение; проверить при первом /qa-regress.
import { test, expect } from '@playwright/test';
import type { Browser, Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { saveSession } from '../_shared/session';
import { enableSharing, disableSharing } from './map-helpers';

const TEL_AVIV = { latitude: 32.0809, longitude: 34.7806, accuracy: 10 };
const OR_AKIVA = { latitude: 32.5067, longitude: 34.9186, accuracy: 10 };
const PILL = 'שיתוף מיקום פעיל';

function baseUrl(): string {
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  return process.env.QA_BASE_URL || cfg.baseUrl;
}

async function phoneAt(browser: Browser, geo: typeof TEL_AVIV): Promise<Page> {
  const ctx = await browser.newContext({
    baseURL: baseUrl(),
    storageState: path.resolve(__dirname, '../../../auth/reg5.json'),
    viewport: { width: 390, height: 844 },
    hasTouch: true,
    isMobile: true,
    locale: 'he-IL',
    geolocation: geo,
    permissions: ['geolocation'],
  });
  return ctx.newPage();
}

test.describe('מיקום — «אני» сразу при входе (#6575d3)', () => {
  test('Шаринг ВКЛ: холодный вход с новым местом → запрос места сразу, «אני» и люди вокруг без переключения тумблера; место возвращено @iphone @data (#6575d3)', async ({ browser }) => {
    test.setTimeout(180_000);
    let wasOff = false;
    // 1. Контекст 1: Тель-Авив, шаринг ВКЛ.
    const first = await phoneAt(browser, TEL_AVIV);
    try {
      await first.goto('/map');
      const pill = first.getByText(PILL);
      const off = first.getByText('שיתוף מיקום כבוי');
      await expect(pill.or(off).first()).toBeVisible();
      if (await off.isVisible()) {
        wasOff = true;
        await enableSharing(first);
      }
      await expect(pill).toBeVisible();
    } finally {
      await saveSession(first, 'reg5');
      await first.context().close();
    }

    // 2. Контекст 2 (холодный): Or-Akiva, тумблер не трогать.
    const second = await phoneAt(browser, OR_AKIVA);
    try {
      const sent: string[] = [];
      second.on('request', (rq) => {
        if (rq.method() !== 'GET' && /record_location|rest\/v1\/rpc\/.*location/.test(rq.url())) sent.push(rq.postData() ?? '');
      });
      const nearby = second.waitForRequest((rq) => rq.url().includes('/rpc/nearby_live') && rq.method() === 'POST', { timeout: 20_000 });
      await second.goto('/map');
      // Запрос обновления места с координатами Or-Akiva (32.5…, 34.9…) уходит сразу, а не через минуту.
      await expect.poll(() => sent.some((b) => /32\.5\d*/.test(b) && /34\.9\d*/.test(b)), { timeout: 10_000, message: 'record_location с координатами Or-Akiva ≤ 10 с' }).toBeTruthy();
      await nearby;
      // «אני» на карте, шаринг остался ВКЛ (тумблер не трогали).
      await expect(second.getByText(PILL)).toBeVisible();
      await expect(second.getByRole('button', { name: 'אני', exact: true }).or(second.getByText('אני', { exact: true })).first()).toBeVisible({ timeout: 10_000 });
    } finally {
      await saveSession(second, 'reg5');
      await second.context().close();
      // 3. Возврат: Тель-Авив (и шаринг как был).
      const back = await phoneAt(browser, TEL_AVIV);
      try {
        await back.goto('/map');
        await expect(back.getByText(PILL).or(back.getByText('שיתוף מיקום כבוי')).first()).toBeVisible();
        if (wasOff) await disableSharing(back);
        else {
          const ping = back.waitForRequest((rq) => rq.method() !== 'GET' && /record_location|rest\/v1\/rpc\/.*location/.test(rq.url()), { timeout: 15_000 }).catch(() => null);
          await ping;
        }
        test.info().annotations.push({ type: 'cleanup', description: `место reg5 возвращено на Тель-Авив; шаринг ${wasOff ? 'выключен обратно' : 'ВКЛ как был'}` });
      } finally {
        await saveSession(back, 'reg5');
        await back.context().close();
      }
    }
  });
});
